function setLang(code) {
  code = String(code || "de").toLowerCase().slice(0, 2);
  LANG = LANGS[code] ? code : "en";
  document.documentElement.lang = LANG;
}
function locale() { return LOCALES[LANG] || "de-DE"; }

/** Übersetzen: t("Text", {platzhalter: wert}) */
function t(s, vars) {
  let r = s;
  if (LANG !== "de" && s) {
    const e = I18N[s];
    if (e) r = e[I18N_ORDER.indexOf(LANG)] || s;
  }
  if (vars) r = String(r).replace(/\{(\w+)\}/g, (m, k) => (vars[k] ?? m));
  return r;
}

/** Statische Texte in index.html (data-i18n, data-i18n-title, -ph, -aria) übersetzen. */
function applyI18n(root = document) {
  for (const el of root.querySelectorAll("[data-i18n]")) el.textContent = t(el.dataset.i18n);
  for (const el of root.querySelectorAll("[data-i18n-title]")) el.title = t(el.dataset.i18nTitle);
  for (const el of root.querySelectorAll("[data-i18n-ph]")) el.placeholder = t(el.dataset.i18nPh);
  for (const el of root.querySelectorAll("[data-i18n-aria]")) el.setAttribute("aria-label", t(el.dataset.i18nAria));
}
